;document.querySelector('.search-form').addEventListener('submit',e=>{e.preventDefault();const q=document.querySelector('#board-search').value.trim();const found=records.filter(r=>r.title.includes(q));document.querySelector('#post-list').innerHTML=q?found.map(r=>'<a class="post-row" href="'+r.path+'"><span class="pill">'+r.category+'</span><div><strong>'+esc(r.title)+'</strong><small>'+r.author+'</small></div><span>↗</span></a>').join('')||'<p class="empty-state">검색 결과가 없습니다.</p>':initial;document.querySelector('#page-label').textContent=q?'검색 결과 '+found.length+'건':initialLabel;document.querySelector('.pagination').hidden=!!q;});